378	    color: var(--accent-hover);
379	    border: 1px solid var(--accent-line);
380	    border-radius: var(--r-pill);
381	    font-size: var(--fs-sm);
382	    font-weight: 600;
383	}
384	
385	.hero-section h1.page-title {
386	    font-size: var(--fs-display);
387	    margin-bottom: var(--s5);
388	}
389	
390	.hero-section h1.page-title span { color: var(--accent); }
391	
392	.hero-section .page-subtitle {
393	    max-width: 620px;
394	    margin: 0 auto;
395	    font-size: 1.08rem;
396	}
397	
398	.hero-actions {
399	    display: flex;
400	    flex-wrap: wrap;
401	    justify-content: center;
402	    gap: var(--s4);
403	    margin-top: var(--s6);
404	}
